        fhir_patient_id: build.fhir_patient_id,
        fhir_url: fhir_url,
        duplicate_source: 'fhir',
        idempotency_key: build.idempotency_key,
        timestamp: new Date().toISOString(),
      },
    },
  }];
}

let message = 'Lab result successfully saved to FHIR.';
if (build.is_panic) {
  message = needs_alert
    ? 'Lab result successfully saved to FHIR. Sending critical alert.'
    : 'Lab result successfully saved to FHIR. Critical alerts are off or Slack is not configured.';
}

return [{
  json: {
    needs_alert: needs_alert,
    alert_text: alert_text,
    slack_webhook_url: needs_alert ? slackUrl : '',
    _started_at_ms: build._started_at_ms,
    http_status: 201,
    response_body: {
      status: 'created',
      success: true,
      result_status: 'created',
      message: message,
      observation_id: observationId,
      fhir_patient_id: build.fhir_patient_id,
      patient_resolution: build.patient_resolution,
      interpretation: build.interpretation,
      is_panic: !!build.is_panic,
      fhir_url: fhir_url,
      alert_sent: false,
      demo_ranges_only: true,
      idempotency_key: build.idempotency_key,
      timestamp: new Date().toISOString(),
    },
  },
}];

const slack = $input.first().json;

function getPrior() {
  try {
    const fromResult = $('Check Result').first().json;
    if (fromResult && fromResult.response_body) return fromResult;
  } catch (e) {}
  try {
    const fromDup = $('Check Duplicate').first().json;
    if (fromDup && fromDup.response_body) return fromDup;
  } catch (e2) {}
  return { response_body: {}, http_status: 201 };
}

const prior = getPrior();
const statusCode = slack.statusCode !== undefined ? Number(slack.statusCode) : (slack.status !== undefined ? Number(slack.status) : 0);
const hasError = !!(slack.error && slack.error.message);
const ok = !hasError && ((statusCode >= 200 && statusCode < 300) || (statusCode === 0 && !hasError));

const idempotency_key = (prior.response_body && prior.response_body.idempotency_key)
  || (function () {
    try { return $('Check Duplicate').first().json.idempotency_key; } catch (e) { return null; }
  })();

const staticData = $getWorkflowStaticData('global');
if (!staticData.processed_results || typeof staticData.processed_results !== 'object') staticData.processed_results = {};

if (!ok) {
  if (idempotency_key && staticData.processed_results[idempotency_key]) {
    staticData.processed_results[idempotency_key].alert_pending = true;
  }
  return [{
    json: {
      _started_at_ms: prior._started_at_ms,
      http_status: 202,
      response_body: {
        status: 'created_alert_failed',
        success: true,
        result_status: 'created',
        error_code: 'ALERT_DELIVERY_FAILED',
        message: 'Lab result was saved to FHIR, but the critical alert could not be delivered. Resend the same result_id to retry the alert only (Observation will not be duplicated).',
        help: 'Check the Slack Incoming Webhook URL in Settings. The Observation is already saved.',
        observation_id: prior.response_body && prior.response_body.observation_id,
        fhir_patient_id: prior.response_body && prior.response_body.fhir_patient_id,
        alert_sent: false,
        alert_pending: true,
        fhir_url: prior.response_body && prior.response_body.fhir_url,
        idempotency_key: idempotency_key,
        timestamp: new Date().toISOString(),
      },
    },
  }];
}

if (idempotency_key && staticData.processed_results[idempotency_key]) {
  staticData.processed_results[idempotency_key].alert_pending = false;
  staticData.processed_results[idempotency_key].alert_text = '';
}

return [{
  json: {
    _started_at_ms: prior._started_at_ms,
    http_status: 201,
    response_body: Object.assign({}, prior.response_body, {
      status: 'created',
      success: true,
      result_status: 'created',
      message: 'Lab result successfully saved to FHIR and critical alert sent.',
      alert_sent: true,
      alert_pending: false,
      timestamp: new Date().toISOString(),
    }),
  },
}];

const item = $input.first().json;
if (item._proceed === false) {
  return [{ json: Object.assign({}, item, { _search_patient: false, _need_create: false }) }];
}

const settings = item._settings || {};
const fhir_base_url = String(settings.fhir_base_url || 'https://hapi.fhir.org/baseR4').replace(/\/$/, '');
const system = String(settings.patient_identifier_system || 'urn:n8n:lab-patient-id').trim() || 'urn:n8n:lab-patient-id';
const patient_id = String(item.patient_id);
const identifierQuery = system + '|' + patient_id;

const patient_resource = {
  resourceType: 'Patient',
  identifier: [{ system: system, value: patient_id }],
};
if (item.patient_name) {
  patient_resource.name = [{ use: 'usual', text: String(item.patient_name) }];
}
if (item.patient_birth_date) {
  patient_resource.birthDate = String(item.patient_birth_date);
}
if (item.patient_gender) {
  patient_resource.gender = String(item.patient_gender);
}

return [{
  json: Object.assign({}, item, {
    _search_patient: true,
    _need_create: false,
    fhir_base_url: fhir_base_url,
    patient_identifier_system: system,
    patient_search_url: fhir_base_url + '/Patient?identifier=' + encodeURIComponent(identifierQuery),
    patient_if_none_exist: 'identifier=' + system + '|' + encodeURIComponent(patient_id),
    patient_resource: patient_resource,
  }),
}];

const prior = $('Prepare Patient Search').first().json;
const response = $input.first().json;

const statusCode = response.statusCode !== undefined ? Number(response.statusCode) : (response.status !== undefined ? Number(response.status) : 0);
const headers = response.headers || {};
const body = (response.body !== undefined) ? response.body : response;

function redact(text) {
  return String(text || '').replace(/Bearer\s+[A-Za-z0-9\-._~+/]+=*/gi, 'Bearer [redacted]').slice(0, 300);
}

function fail(http_status, help, diagnostic) {
  return [{
    json: {
      _proceed: false,
      _need_create: false,
      _started_at_ms: prior._started_at_ms,
      http_status: http_status,
      response_body: {
        status: 'fhir_error',
        success: false,
        error_code: 'PATIENT_FHIR_ERROR',
        message: 'Could not resolve the patient in FHIR.',
        help: help,
        details: { upstream_status: statusCode, diagnostic: redact(diagnostic) },
        timestamp: new Date().toISOString(),
      },
    },
  }];
}

if (statusCode === 401 || statusCode === 403) {
  return fail(502, 'FHIR authentication failed. Set the same Bearer YOUR_TOKEN_HERE credential on Find Patient, Create Patient, and Send Observation.', 'Authentication rejected by FHIR server.');
}
if (statusCode >= 500 || statusCode === 0 || !!(response.error && response.error.message)) {
  const diagnostic = (response.error && response.error.message) ? response.error.message : 'FHIR Patient search failed.';
  return fail(503, 'FHIR server unavailable or timed out during Patient search. Retry later.', diagnostic);
}
if (statusCode < 200 || statusCode >= 300) {
  let diagnostic = 'Unexpected Patient search response.';
  if (body && body.resourceType === 'OperationOutcome' && Array.isArray(body.issue)) {
    diagnostic = body.issue.map(function (i) { return i.diagnostics || (i.details && i.details.text) || i.code; }).filter(Boolean).join('; ') || diagnostic;
  }
  return fail(502, 'Check FHIR Base URL and Patient Identifier System in Settings.', diagnostic);
}

// Only treat a well-formed FHIR Bundle (or a single Patient) as a valid search result.
// Never create a Patient from an unexpected 200 body.
let patients = [];
let validSearchResponse = false;

if (body && body.resourceType === 'Bundle') {
  validSearchResponse = true;
  patients = (body.entry || []).map(function (e) { return e && e.resource; }).filter(function (r) { return r && r.resourceType === 'Patient' && r.id; });
  if (typeof body.total === 'number' && body.total > 0 && patients.length === 0) {
    return fail(502, 'Patient search returned matches but no usable Patient resources. Check FHIR server search behavior.', 'Bundle.total=' + body.total + ' but no Patient entries with ids.');
  }
  if (typeof body.total === 'number' && body.total > patients.length && patients.length >= 1) {
    if (body.total > 1) {
      return [{
        json: {
          _proceed: false,
          _need_create: false,
          http_status: 409,
          _started_at_ms: prior._started_at_ms,
          response_body: {
            status: 'patient_ambiguous',
            success: false,
            error_code: 'PATIENT_AMBIGUOUS',
            message: 'Multiple patients may match this external patient_id. Resolve duplicates in FHIR before retrying.',
            errors: [{
              field: 'patient_id',
              issue: 'Bundle.total is ' + body.total + ' for identifier ' + prior.patient_identifier_system + '|' + prior.patient_id + '.',
            }],
            match_count: body.total,
            timestamp: new Date().toISOString(),
          },
        },
      }];
    }
  }
} else if (body && body.resourceType === 'Patient' && body.id) {
  validSearchResponse = true;
  patients = [body];
} else if (body && body.resourceType === 'OperationOutcome') {
  let diagnostic = 'Patient search returned OperationOutcome.';
  if (Array.isArray(body.issue)) {
    diagnostic = body.issue.map(function (i) { return i.diagnostics || (i.details && i.details.text) || i.code; }).filter(Boolean).join('; ') || diagnostic;
  }
  return fail(502, 'Check FHIR Base URL, Patient Identifier System, and search permissions.', diagnostic);
}

if (!validSearchResponse) {
  return fail(502, 'Patient search returned an unexpected response. Expected a FHIR Bundle. Do not retry create until search works.', 'Unexpected Patient search body (not a Bundle or Patient).');
}

if (patients.length > 1) {
  return [{
    json: {
      _proceed: false,
      _need_create: false,
      http_status: 409,
      _started_at_ms: prior._started_at_ms,
      response_body: {
        status: 'patient_ambiguous',
        success: false,
        error_code: 'PATIENT_AMBIGUOUS',
        message: 'Multiple patients match this external patient_id. Resolve the duplicates in FHIR before retrying.',
        errors: [{
          field: 'patient_id',
          issue: 'Expected exactly one Patient for identifier ' + prior.patient_identifier_system + '|' + prior.patient_id + '; found ' + patients.length + '.',
        }],
        match_count: patients.length,
        timestamp: new Date().toISOString(),
      },
    },
  }];
}

if (patients.length === 1) {
  return [{
    json: Object.assign({}, prior, {
      _proceed: true,
      _need_create: false,
      fhir_patient_id: String(patients[0].id),
      patient_resolution: 'found',
    }),
  }];
}

// Valid Bundle with zero Patient matches - safe to create
return [{
  json: Object.assign({}, prior, {
    _proceed: true,
    _need_create: true,
    patient_resolution: 'create',
  }),
}];

function coerceHttpBody(body) {
  if (body == null) return body;
  if (typeof body === 'string') {
    try { return JSON.parse(body); } catch (e) { return body; }
  }
  if (typeof body === 'object' && body.resourceType) return body;
  if (typeof Buffer !== 'undefined' && typeof body === 'object' && body.type === 'Buffer' && Array.isArray(body.data)) {
    try { return JSON.parse(Buffer.from(body.data).toString('utf8')); } catch (e) { return body; }
  }
  if (typeof body === 'object' && body._readableState && Array.isArray(body._readableState.buffer)) {
    try {
      const bytes = [];
      body._readableState.buffer.forEach(function (c) {
        if (c && Array.isArray(c.data)) Array.prototype.push.apply(bytes, c.data);
      });
      if (bytes.length) return JSON.parse(Buffer.from(bytes).toString('utf8'));
    } catch (e2) {}
  }
  return body;
}

const prior = $('Check Patient').first().json;
const response = $input.first().json;

const statusCode = response.statusCode !== undefined ? Number(response.statusCode) : (response.status !== undefined ? Number(response.status) : 0);
const headers = response.headers || {};
const body = coerceHttpBody((response.body !== undefined) ? response.body : response);

function redact(text) {
  return String(text || '').replace(/Bearer\s+[A-Za-z0-9\-._~+/]+=*/gi, 'Bearer [redacted]').slice(0, 300);
}

function fail(http_status, help, diagnostic) {
  return [{
    json: {
      _proceed: false,
      _need_create: false,
      _started_at_ms: prior._started_at_ms,
      http_status: http_status,
      response_body: {
        status: 'fhir_error',
        success: false,
        error_code: 'PATIENT_FHIR_ERROR',
        message: 'Could not create the patient in FHIR.',
        help: help,
        details: { upstream_status: statusCode, diagnostic: redact(diagnostic) },
        timestamp: new Date().toISOString(),
      },
    },
  }];
}

let patientId = null;
if (body && typeof body === 'object' && body.resourceType === 'Patient' && body.id) {
  patientId = String(body.id);
}
const location = headers.location || headers.Location || '';
if (!patientId && typeof location === 'string' && location.indexOf('/Patient/') !== -1) {
  patientId = location.split('/Patient/')[1].split(/[/?]/)[0];
}

if (statusCode === 401 || statusCode === 403) {
  return fail(502, 'FHIR authentication failed. Set the same Bearer YOUR_TOKEN_HERE credential on Search Patient, Create Patient, and POST Observation.', 'Authentication rejected by FHIR server.');
}

const ok = ((statusCode >= 200 && statusCode < 300) || (statusCode === 0 && !response.error && !!patientId)) && !!patientId;
if (!ok) {
  let diagnostic = 'The FHIR server could not create this Patient.';
  if (body && body.resourceType === 'OperationOutcome' && Array.isArray(body.issue)) {
    diagnostic = body.issue.map(function (i) { return i.diagnostics || (i.details && i.details.text) || i.code; }).filter(Boolean).join('; ') || diagnostic;
  } else if (response.error && response.error.message) {
    diagnostic = String(response.error.message);
  }
  const http_status = (statusCode >= 500 || statusCode === 0 || !!(response.error && response.error.message)) ? 503 : 502;
  const help = http_status === 503
    ? 'FHIR server unavailable or timed out during Patient create. Retry later.'
    : 'Check FHIR Base URL, Patient Identifier System, and create permissions.';
  return fail(http_status, help, diagnostic);
}

return [{
  json: Object.assign({}, prior, {
    _proceed: true,
    _need_create: false,
    fhir_patient_id: patientId,
    patient_resolution: statusCode === 200 ? 'existing' : 'created',
  }),
}];

const item = $input.first().json;
const response_body = Object.assign({}, (item && item.response_body) || {});

const ERROR_CODES = {
  validation_error: 'VALIDATION_ERROR',
  unsupported_test: 'UNSUPPORTED_TEST',
  unit_mismatch: 'UNIT_MISMATCH',
  patient_ambiguous: 'PATIENT_AMBIGUOUS',
  fhir_error: 'FHIR_ERROR',
  created_alert_failed: 'ALERT_DELIVERY_FAILED',
};

const status = response_body.status;
const isDuplicate = status === 'duplicate';
const isCreated = status === 'created' || status === 'created_alert_failed';
const success = isDuplicate || isCreated;

response_body.success = (response_body.success !== undefined) ? !!response_body.success : success;

if (isDuplicate) {
  response_body.result_status = 'duplicate';
} else if (isCreated) {
  response_body.result_status = 'created';
}

if (!response_body.success) {
  if (!response_body.error_code) {
    if (status === 'fhir_error' && response_body.message && String(response_body.message).toLowerCase().indexOf('patient') !== -1) {
      response_body.error_code = 'PATIENT_FHIR_ERROR';
    } else if (status === 'fhir_error') {
      response_body.error_code = 'OBSERVATION_FHIR_ERROR';
    } else {
      response_body.error_code = ERROR_CODES[status] || 'PROCESSING_ERROR';
    }
  }
  if (!response_body.message) {
    response_body.message = 'Request could not be processed.';
  }
}

const started = item._started_at_ms;
if (typeof started === 'number' && Number.isFinite(started)) {
  response_body.processing_duration_ms = Math.max(0, Date.now() - started);
} else if (typeof response_body.processing_duration_ms !== 'number') {
  response_body.processing_duration_ms = 0;
}

if (!response_body.timestamp) {
  response_body.timestamp = new Date().toISOString();
}

return [{
  json: {
    http_status: item.http_status || (response_body.success ? (isDuplicate ? 200 : 201) : 500),
    response_body: response_body,
  },
}];
